function runSelfTests(){var failures=[];function assert(condition,message){if(!condition)failures.push(message);}assert(new Set(CATEGORIES.map(function(c){return c.id;})).size===CATEGORIES.length,"duplicate category id");assert(new Set(FAMILIES.map(function(f){return f.id;})).size===FAMILIES.length,"duplicate family id");assert(FAMILIES.length===25,"all 25 batch-one families registered");FAMILIES.forEach(function(f,familyIndex){assert(CATEGORIES.some(function(c){return c.id===f.categoryId;}),f.id+": category exists");LEVELS.forEach(function(level){var signatures=new Set();for(var sample=0;sample<32;sample+=1){var seed=((familyIndex+1)*100000+level*1000+sample+1)>>>0;try{var q=generateQuestion(f.id,level,seed);assert(q.familyId===f.id,f.id+": stable family id");assert(q.prompt.title&&q.explanation,f.id+": rendering metadata");assert(checkQuestion(q.canonicalAnswer,q).correct,f.id+": canonical answer rejected L"+level+" seed "+seed);assert(!checkQuestion({},q).correct,f.id+": empty malformed answer accepted");assert(q.metadata.modelId===MODEL_ID&&q.metadata.oracleVersion===ORACLE_VERSION,f.id+": pinned model metadata");assert(q.metadata.packetModel&&q.metadata.syntheticState,f.id+": semantic metadata");signatures.add(q.structuralSignature);}catch(error){failures.push(f.id+" L"+level+" seed "+seed+": "+error.message);}}assert(signatures.size>=2,f.id+": insufficient structural variation L"+level);});});assert(hexN(inetChecksum([0x4500,0x001C,0x0000]),4)==="BAE3","checksum landmark BAE3");assert(hexN(inetChecksum([0xFFFF,0x0001]),4)==="FFFE","end-around carry landmark");assert(dump(beBytes(0x0800,2))==="08 00"&&beValue([0x01,0xBB])===443&&beValue([0x12,0x34,0x00,0x05])===0x12340005,"network byte order landmarks");var fp=fragmentPlan(2000,20,1500);assert(fp.length===2&&fp[0].len===1480&&fp[1].off/8===185&&fp[1].len===520&&!fp[1].mf&&fp[0].mf,"fragment plan landmark");var fp3=fragmentPlan(4000,20,1500);assert(fp3.map(function(f){return f.len;}).join()==="1480,1480,1040"&&fp3[2].off/8===370,"three-fragment landmark");assert(fragmentPlan(1480,20,1500).length===1,"exact-MTU packet is not fragmented");assert(reassemble([{id:1,off:185,len:520,mf:false},{id:1,off:0,len:1480,mf:true}]).len===2000,"reassembly landmark");assert(reassemble([{id:1,off:0,len:1480,mf:true},{id:1,off:186,len:512,mf:false}]).status==="gap","reassembly gap landmark");assert(v6Format(v6Parse("2001:0db8:0000:0000:0001:0000:0000:0009"))==="2001:db8::1:0:0:9"&&v6Format(v6Parse("2001:db8::"))==="2001:db8::","IPv6 compression landmarks");assert(inPrefix6("2001:db8:1::9","2001:db8:1::",48)&&!inPrefix6("2001:db8:2::9","2001:db8:1::",48)&&inPrefix4("10.2.3.4","10.2.0.0",16)&&!inPrefix4("10.3.3.4","10.2.0.0",16),"prefix landmarks");var ws=wordsOf(ipv4Header({totalLength:60,id:1,ttl:64,protocol:6,src:"192.0.2.1",dst:"198.51.100.2"}));assert(onesSum(ws)===0xFFFF,"serialized IPv4 header verifies");FAMILIES.forEach(function(f){LEVELS.forEach(function(level){for(var s1=0;s1<40;s1+=1){var q1=generateQuestion(f.id,level,(level*7919+s1*104729+1)>>>0);q1.fields.forEach(function(fd){if(fd.kind==="choice"){assert(fd.options.length>=2,f.id+" L"+level+": choice field "+fd.id+" has fewer than two options");assert(new Set(fd.options.map(function(o){return o.label;})).size===fd.options.length,f.id+" L"+level+": duplicate option labels");assert(fd.options.some(function(o){return o.value===fd.answer;}),f.id+" L"+level+": answer missing from options");}});}});});assert(Object.keys(TEMPLATE_CONFLICTS).length===0,"template keys reused with different English: "+Object.keys(TEMPLATE_CONFLICTS).join(","));if(TEXT.localeCode!=="en")USED_TEMPLATE_KEYS.forEach(function(k){assert(TEXT.gen&&Object.prototype.hasOwnProperty.call(TEXT.gen,k),"Swedish template "+k);});if(TEXT.localeCode!=="en"){assert(CATEGORIES.every(function(c){return Boolean(t("categories."+c.id,null));}),"localized categories complete");assert(FAMILIES.every(function(f){return Boolean(t("families."+f.id,null)&&t("familyRules."+f.id,null)&&t("familyExamples."+f.id,null));}),"localized family learn content complete");}return{ok:failures.length===0,failures:failures};}
